use std::cell::Cell;

use worker::{SqlStorage, SqlStorageValue};

use crate::store::{migrate, run};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Lock {
    pub pin_hash: String,
    pub generation: u64,
}

impl Lock {
    pub fn is_locked(&self) -> bool {
        !self.pin_hash.is_empty()
    }
}

pub struct SqlLockStore {
    sql: SqlStorage,
    migrated: Cell<bool>,
}

fn integer(value: i64) -> Result<u64, String> {
    u64::try_from(value).map_err(|e| e.to_string())
}

impl SqlLockStore {
    pub fn new(sql: SqlStorage) -> Self {
        SqlLockStore {
            sql,
            migrated: Cell::new(false),
        }
    }

    fn migrate(&self) -> Result<(), String> {
        if !self.migrated.get() {
            migrate(&self.sql)?;
            self.migrated.set(true);
        }
        Ok(())
    }

    fn row(
        &self,
        query: &str,
        bindings: Vec<SqlStorageValue>,
    ) -> Result<Option<Vec<SqlStorageValue>>, String> {
        self.migrate()?;
        self.sql
            .exec(query, bindings)
            .map_err(|e| e.to_string())?
            .raw()
            .next()
            .transpose()
            .map_err(|e| e.to_string())
    }

    pub fn lock(&self) -> Result<Lock, String> {
        match self
            .row(
                "SELECT pin_hash, generation FROM board_lock WHERE lock_id = 1",
                vec![],
            )?
            .as_deref()
        {
            None => Ok(Lock {
                pin_hash: String::new(),
                generation: 0,
            }),
            Some(
                [
                    SqlStorageValue::String(pin_hash),
                    SqlStorageValue::Integer(generation),
                ],
            ) => Ok(Lock {
                pin_hash: pin_hash.clone(),
                generation: integer(*generation)?,
            }),
            Some(other) => Err(format!("board_lock returned a malformed row: {other:?}")),
        }
    }

    pub fn set_pin_hash(&self, pin_hash: &str) -> Result<Lock, String> {
        let next = Lock {
            pin_hash: pin_hash.to_owned(),
            generation: self.lock()?.generation + 1,
        };
        let generation = i64::try_from(next.generation).map_err(|e| e.to_string())?;
        run(
            &self.sql,
            "INSERT INTO board_lock (lock_id, pin_hash, generation) VALUES (1, ?, ?)
             ON CONFLICT (lock_id)
             DO UPDATE SET pin_hash = excluded.pin_hash, generation = excluded.generation",
            vec![pin_hash.into(), generation.into()],
        )?;
        Ok(next)
    }

    pub fn attempts(&self, client: &str) -> Result<Vec<u64>, String> {
        match self
            .row(
                "SELECT attempts FROM pin_attempt WHERE client = ?",
                vec![client.into()],
            )?
            .as_deref()
        {
            None => Ok(Vec::new()),
            Some([SqlStorageValue::String(attempts)]) => serde_json::from_str(attempts)
                .map_err(|e| format!("pin_attempt for {client:?} is not a JSON list: {e}")),
            Some(other) => Err(format!("pin_attempt returned a malformed row: {other:?}")),
        }
    }

    pub fn record_attempts(
        &self,
        client: &str,
        attempts: &[u64],
        now_ms: u64,
        window_ms: u64,
    ) -> Result<(), String> {
        let now = i64::try_from(now_ms).map_err(|e| e.to_string())?;
        let stale = i64::try_from(now_ms.saturating_sub(window_ms)).map_err(|e| e.to_string())?;
        let attempts = serde_json::to_string(attempts).map_err(|e| e.to_string())?;
        run(
            &self.sql,
            "DELETE FROM pin_attempt WHERE updated_at < ?",
            vec![stale.into()],
        )?;
        run(
            &self.sql,
            "INSERT INTO pin_attempt (client, attempts, updated_at) VALUES (?, ?, ?)
             ON CONFLICT (client)
             DO UPDATE SET attempts = excluded.attempts, updated_at = excluded.updated_at",
            vec![client.into(), attempts.into(), now.into()],
        )
    }
}
use std::cell::Cell;

use worker::{SqlStorage, SqlStorageValue};

use crate::object::Bbox;
use crate::view::LevelRange;

pub type TileCoord = (i32, i64, i64);

#[derive(Debug, Clone, PartialEq)]
pub struct TileRecord {
    pub coord: TileCoord,
    pub doc_state: Vec<u8>,
    pub updated_at: u64,
    pub objects: Vec<(String, Bbox)>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct TileSnapshot {
    pub coord: TileCoord,
    pub doc_state: Vec<u8>,
    pub objects: usize,
}

pub trait TileStore {
    fn load(&self, coord: TileCoord) -> Result<Option<Vec<u8>>, String>;
    /// Writes every record or none. The Durable Object commits the synchronous writes of one
    /// event, with no await between them, as a single transaction.
    fn save_all(&self, records: &[TileRecord]) -> Result<(), String>;
    /// Tiles whose flushed index holds `object_id`.
    fn locate(&self, object_id: &str) -> Result<Vec<TileCoord>, String>;
    /// Tiles in `range` that hold objects, nearest to `center` first, cut before the
    /// running object count passes `budget`.
    fn range(
        &self,
        range: &LevelRange,
        center: (i64, i64),
        budget: usize,
    ) -> Result<Vec<TileSnapshot>, String>;
}

const RANGE_QUERY: &str = "SELECT c.tx, c.ty, t.doc_state, c.n FROM (
        SELECT tx, ty, n, SUM(n) OVER (ORDER BY ring, ty, tx ROWS UNBOUNDED PRECEDING) AS running
        FROM (
            SELECT tx, ty, COUNT(*) AS n, MAX(ABS(tx - ?), ABS(ty - ?)) AS ring
            FROM object_index
            WHERE level = ? AND tx BETWEEN ? AND ? AND ty BETWEEN ? AND ?
            GROUP BY tx, ty
        )
    ) c
    JOIN tile t ON t.level = ? AND t.tx = c.tx AND t.ty = c.ty
    WHERE c.running <= ?
    ORDER BY c.running";

pub const MIGRATIONS: &[&[&str]] = &[
    &[
        "CREATE TABLE tile (
        level INTEGER NOT NULL,
        tx INTEGER NOT NULL,
        ty INTEGER NOT NULL,
        doc_state BLOB NOT NULL,
        updated_at INTEGER NOT NULL,
        PRIMARY KEY (level, tx, ty)
    )",
        "CREATE TABLE object_index (
        level INTEGER NOT NULL,
        tx INTEGER NOT NULL,
        ty INTEGER NOT NULL,
        object_id TEXT NOT NULL,
        bbox TEXT NOT NULL,
        PRIMARY KEY (level, tx, ty, object_id)
    )",
    ],
    &["CREATE INDEX object_index_object ON object_index (object_id)"],
    &[
        "CREATE TABLE board_lock (
        lock_id INTEGER PRIMARY KEY CHECK (lock_id = 1),
        pin_hash TEXT NOT NULL,
        generation INTEGER NOT NULL
    )",
        "CREATE TABLE pin_attempt (
        client TEXT PRIMARY KEY,
        attempts TEXT NOT NULL,
        updated_at INTEGER NOT NULL
    )",
    ],
];

pub fn bbox_json(bbox: &Bbox) -> String {
    format!(
        "[{},{},{},{}]",
        bbox.min_x, bbox.min_y, bbox.max_x, bbox.max_y
    )
}

pub struct SqlTileStore {
    sql: SqlStorage,
    migrated: Cell<bool>,
}

fn coord_bindings((level, tx, ty): TileCoord) -> Vec<SqlStorageValue> {
    vec![level.into(), tx.into(), ty.into()]
}

impl SqlTileStore {
    pub fn new(sql: SqlStorage) -> Self {
        SqlTileStore {
            sql,
            migrated: Cell::new(false),
        }
    }

    fn run(&self, query: &str, bindings: Vec<SqlStorageValue>) -> Result<(), String> {
        run(&self.sql, query, bindings)
    }

    fn save(&self, record: &TileRecord) -> Result<(), String> {
        let updated_at = i64::try_from(record.updated_at).map_err(|e| e.to_string())?;
        let mut bindings = coord_bindings(record.coord);
        bindings.push(record.doc_state.clone().into());
        bindings.push(updated_at.into());
        self.run(
            "INSERT INTO tile (level, tx, ty, doc_state, updated_at) VALUES (?, ?, ?, ?, ?)
             ON CONFLICT (level, tx, ty)
             DO UPDATE SET doc_state = excluded.doc_state, updated_at = excluded.updated_at",
            bindings,
        )?;
        self.run(
            "DELETE FROM object_index WHERE level = ? AND tx = ? AND ty = ?",
            coord_bindings(record.coord),
        )?;
        for (object_id, bbox) in &record.objects {
            let mut bindings = coord_bindings(record.coord);
            bindings.push(object_id.as_str().into());
            bindings.push(bbox_json(bbox).into());
            self.run(
                "INSERT INTO object_index (level, tx, ty, object_id, bbox) VALUES (?, ?, ?, ?, ?)",
                bindings,
            )?;
        }
        Ok(())
    }

    fn migrate(&self) -> Result<(), String> {
        if !self.migrated.get() {
            migrate(&self.sql)?;
            self.migrated.set(true);
        }
        Ok(())
    }
}

pub fn run(sql: &SqlStorage, query: &str, bindings: Vec<SqlStorageValue>) -> Result<(), String> {
    let cursor = sql.exec(query, bindings).map_err(|e| e.to_string())?;
    for row in cursor.raw() {
        row.map_err(|e| e.to_string())?;
    }
    Ok(())
}

pub fn migrate(sql: &SqlStorage) -> Result<(), String> {
    run(
        sql,
        "CREATE TABLE IF NOT EXISTS schema_migration (version INTEGER PRIMARY KEY)",
        vec![],
    )?;
    let current = sql
        .exec(
            "SELECT COALESCE(MAX(version), 0) FROM schema_migration",
            None,
        )
        .map_err(|e| e.to_string())?
        .raw()
        .next()
        .transpose()
        .map_err(|e| e.to_string())?;
    let applied = match current.as_deref() {
        Some([SqlStorageValue::Integer(v)]) => usize::try_from(*v).unwrap_or(0),
        _ => 0,
    };
    for (index, steps) in MIGRATIONS.iter().enumerate().skip(applied) {
        for step in *steps {
            run(sql, step, vec![])?;
        }
        let version = i64::try_from(index + 1).map_err(|e| e.to_string())?;
        run(
            sql,
            "INSERT INTO schema_migration (version) VALUES (?)",
            vec![version.into()],
        )?;
    }
    Ok(())
}

impl TileStore for SqlTileStore {
    fn save_all(&self, records: &[TileRecord]) -> Result<(), String> {
        self.migrate()?;
        for record in records {
            self.save(record)?;
        }

