export const DEFAULT_BOARD = "default";

export type RecentBoard = {
  id: string;
  name: string;
  lastOpened: number;
  thumbnail: string;
};

export const RECENTS_KEY = "stallion:recents";

export const MAX_RECENTS = 50;

type RecentsStorage = Pick<Storage, "getItem" | "setItem">;

const isRecentBoard = (value: unknown): value is RecentBoard => {
  if (typeof value !== "object" || value === null) return false;
  const { id, name, lastOpened, thumbnail } = value as Record<string, unknown>;
  return (
    typeof id === "string" &&
    typeof name === "string" &&
    typeof lastOpened === "number" &&
    typeof thumbnail === "string"
  );
};

const seedDefault = (): RecentBoard[] => [
  { id: DEFAULT_BOARD, name: DEFAULT_BOARD, lastOpened: 0, thumbnail: "" },
];

export const loadRecents = (storage: RecentsStorage): RecentBoard[] => {
  const raw = storage.getItem(RECENTS_KEY);
  if (raw === null) return seedDefault();
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter(isRecentBoard) : [];
  } catch {
    return [];
  }
};

export const saveRecents = (storage: RecentsStorage, recents: readonly RecentBoard[]): void => {
  try {
    storage.setItem(RECENTS_KEY, JSON.stringify(recents));
  } catch {
    // Recents are a per-device convenience; losing a write only forgets recency.
  }
};

const sortByRecency = (recents: readonly RecentBoard[]): RecentBoard[] =>
  [...recents].sort((a, b) => b.lastOpened - a.lastOpened).slice(0, MAX_RECENTS);

export type RecentPatch = { id: string } & Partial<Omit<RecentBoard, "id">>;

export const upsertRecent = (
  recents: readonly RecentBoard[],
  patch: RecentPatch,
): RecentBoard[] => {
  const existing = recents.find((recent) => recent.id === patch.id);
  const merged: RecentBoard = {
    id: patch.id,
    name: patch.name ?? existing?.name ?? patch.id,
    lastOpened: patch.lastOpened ?? Date.now(),
    thumbnail: patch.thumbnail ?? existing?.thumbnail ?? "",
  };
  const rest = recents.filter((recent) => recent.id !== patch.id);
  return sortByRecency([merged, ...rest]);
};

export const removeRecent = (recents: readonly RecentBoard[], id: string): RecentBoard[] =>
  recents.filter((recent) => recent.id !== id);

export const renameRecent = (
  recents: readonly RecentBoard[],
  id: string,
  name: string,
): RecentBoard[] => recents.map((recent) => (recent.id === id ? { ...recent, name } : recent));
import { describe, expect, it } from "vitest";
import {
  DEFAULT_BOARD,
  loadRecents,
  MAX_RECENTS,
  RECENTS_KEY,
  type RecentBoard,
  removeRecent,
  renameRecent,
  saveRecents,
  upsertRecent,
} from "./recents";

class FakeStorage {
  private data = new Map<string, string>();
  getItem(key: string): string | null {
    return this.data.has(key) ? (this.data.get(key) ?? null) : null;
  }
  setItem(key: string, value: string): void {
    this.data.set(key, value);
  }
}

const board = (id: string, lastOpened: number): RecentBoard => ({
  id,
  name: id,
  lastOpened,
  thumbnail: "",
});

describe("loadRecents", () => {
  it("seeds the default board on a device that has never stored recents", () => {
    expect(loadRecents(new FakeStorage())).toEqual([
      { id: DEFAULT_BOARD, name: DEFAULT_BOARD, lastOpened: 0, thumbnail: "" },
    ]);
  });

  it("returns an empty list once the key exists but every entry was removed", () => {
    const storage = new FakeStorage();
    storage.setItem(RECENTS_KEY, "[]");
    expect(loadRecents(storage)).toEqual([]);
  });

  it("drops malformed entries instead of throwing", () => {
    const storage = new FakeStorage();
    storage.setItem(RECENTS_KEY, JSON.stringify([{ id: "ok", name: "ok" }, "junk", 42]));
    expect(loadRecents(storage)).toEqual([]);
  });

  it("recovers from corrupt JSON", () => {
    const storage = new FakeStorage();
    storage.setItem(RECENTS_KEY, "{not json");
    expect(loadRecents(storage)).toEqual([]);
  });
});

describe("saveRecents", () => {
  it("round-trips through the storage key", () => {
    const storage = new FakeStorage();
    const recents = [board("a", 1)];
    saveRecents(storage, recents);
    expect(loadRecents(storage)).toEqual(recents);
  });
});

describe("upsertRecent", () => {
  it("puts a newly opened board at the front", () => {
    const recents = [board("a", 1)];
    const next = upsertRecent(recents, { id: "b", lastOpened: 2 });
    expect(next.map((r) => r.id)).toEqual(["b", "a"]);
  });

  it("moves a reopened board back to the front and keeps its name", () => {
    const recents = [board("a", 3), board("b", 2), board("c", 1)];
    const named = renameRecent(recents, "c", "My old board");
    const next = upsertRecent(named, { id: "c", lastOpened: 4 });
    expect(next.map((r) => r.id)).toEqual(["c", "a", "b"]);
    expect(next[0]).toMatchObject({ name: "My old board", lastOpened: 4 });
  });

  it("defaults a new board's name to its id", () => {
    const next = upsertRecent([], { id: "fresh-id", lastOpened: 1 });
    expect(next[0]).toMatchObject({ id: "fresh-id", name: "fresh-id" });
  });

  it("caps the list at 50, dropping the oldest", () => {
    const recents = Array.from({ length: MAX_RECENTS }, (_, i) => board(`id-${i}`, i));
    const next = upsertRecent(recents, { id: "newest", lastOpened: MAX_RECENTS });
    expect(next).toHaveLength(MAX_RECENTS);
    expect(next[0]?.id).toBe("newest");
    expect(next.some((r) => r.id === "id-0")).toBe(false);
  });
});

describe("removeRecent", () => {
  it("forgets one board without touching the rest", () => {
    const recents = [board("a", 2), board("b", 1)];
    expect(removeRecent(recents, "a")).toEqual([board("b", 1)]);
  });
});

describe("renameRecent", () => {
  it("renames one board in place", () => {
    const recents = [board("a", 2), board("b", 1)];
    const next = renameRecent(recents, "b", "Sketchbook");
    expect(next.find((r) => r.id === "b")).toMatchObject({ name: "Sketchbook" });
    expect(next.find((r) => r.id === "a")).toMatchObject({ name: "a" });
  });
});
import { useState } from "preact/hooks";
import { useLocation } from "wouter-preact";
import { randomBoardId } from "./id";
import { loadRecents, type RecentBoard, removeRecent, renameRecent, saveRecents } from "./recents";

const MINUTE_MS = 60_000;

const RELATIVE_UNITS: readonly [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 365 * 24 * 60 * MINUTE_MS],
  ["month", 30 * 24 * 60 * MINUTE_MS],
  ["week", 7 * 24 * 60 * MINUTE_MS],
  ["day", 24 * 60 * MINUTE_MS],
  ["hour", 60 * MINUTE_MS],
  ["minute", MINUTE_MS],
];

const relativeTimeFormat = new Intl.RelativeTimeFormat("en", { numeric: "auto" });

const relativeTime = (from: number, now: number): string => {
  const diff = Math.max(0, now - from);
  if (diff < MINUTE_MS) return "just now";
  for (const [unit, unitMs] of RELATIVE_UNITS) {
    if (diff >= unitMs) return relativeTimeFormat.format(-Math.round(diff / unitMs), unit);
  }
  return relativeTimeFormat.format(-Math.round(diff / MINUTE_MS), "minute");
};

export const lastOpenedLabel = (lastOpened: number, now: number): string =>
  lastOpened ? relativeTime(lastOpened, now) : "not opened yet";

export function Landing() {
  const [, navigate] = useLocation();
  const [recents, setRecents] = useState<RecentBoard[]>(() => loadRecents(localStorage));

  const createBoard = () => navigate(`/b/${randomBoardId()}`);

  const editName = (id: string, name: string) => {
    setRecents((current) => renameRecent(current, id, name));
  };

  const commitNames = () => {
    setRecents((current) => {
      saveRecents(localStorage, current);
      return current;
    });
  };

  const remove = (id: string) => {
    setRecents((current) => {
      const next = removeRecent(current, id);
      saveRecents(localStorage, next);
      return next;
    });
  };

  return (
    <main class="landing">
      <header class="landing-header">
        <h1>Stallion</h1>
        <button type="button" class="new-board" onClick={createBoard}>
          New board
        </button>
      </header>
      {recents.length > 0 && (
        <ul class="recents">
          {recents.map((recent) => (
            <li key={recent.id} class="recent">
              <button
                type="button"
                class="recent-open"
                onClick={() => navigate(`/b/${recent.id}`)}
                aria-label={`Open board ${recent.name}`}
              >
                {recent.thumbnail ? (
                  <img class="recent-thumb" src={recent.thumbnail} alt="" />
                ) : (
                  <span class="recent-thumb recent-thumb-empty" aria-hidden="true" />
                )}
                <span class="recent-time">{lastOpenedLabel(recent.lastOpened, Date.now())}</span>
              </button>
              <input
                class="recent-name"
                value={recent.name}
                aria-label={`Name for board ${recent.id}`}
                onInput={(event) => editName(recent.id, event.currentTarget.value)}
                onBlur={commitNames}
                onKeyDown={(event) => {
                  if (event.key === "Enter") event.currentTarget.blur();
                }}
              />
              <button
                type="button"
                class="recent-remove"
                aria-label={`Forget board ${recent.name}`}
                title="Remove from this device's recent boards"
                onClick={() => remove(recent.id)}
              >
                <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
                  <path
                    d="M6 6l12 12M18 6L6 18"
                    fill="none"
                    stroke="currentColor"
                    stroke-width="2"
                    stroke-linecap="round"
                  />
                </svg>
              </button>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}
import { PAPER } from "./surface";

export const THUMBNAIL_WIDTH = 160;

const BLANK_TOLERANCE = 4;

const paperRgb = (() => {
  const hex = PAPER.replace("#", "");
  return {
    r: Number.parseInt(hex.slice(0, 2), 16),
    g: Number.parseInt(hex.slice(2, 4), 16),
    b: Number.parseInt(hex.slice(4, 6), 16),
  };
})();

const isBlank = (data: Uint8ClampedArray): boolean => {
  for (let i = 0; i < data.length; i += 4) {
    const dr = Math.abs((data[i] ?? 0) - paperRgb.r);
    const dg = Math.abs((data[i + 1] ?? 0) - paperRgb.g);
    const db = Math.abs((data[i + 2] ?? 0) - paperRgb.b);
    if (dr > BLANK_TOLERANCE || dg > BLANK_TOLERANCE || db > BLANK_TOLERANCE) return false;
  }
  return true;
};

export const captureThumbnail = (canvas: HTMLCanvasElement): string | undefined => {
  if (canvas.width === 0 || canvas.height === 0) return undefined;
  const width = THUMBNAIL_WIDTH;
  const height = Math.max(1, Math.round((canvas.height / canvas.width) * width));
  const offscreen = document.createElement("canvas");
  offscreen.width = width;
  offscreen.height = height;
  const ctx = offscreen.getContext("2d");
  if (!ctx) return undefined;
  ctx.drawImage(canvas, 0, 0, width, height);
  if (isBlank(ctx.getImageData(0, 0, width, height).data)) return undefined;
  return offscreen.toDataURL("image/png");
};
