      return undefined;
    }
  },
  set(boardId, pass) {
    try {
      storage()?.setItem(passKey(boardId), pass);
    } catch {
      return;
    }
  },
  remove(boardId) {
    try {
      storage()?.removeItem(passKey(boardId));
    } catch {
      return;
    }
  },
