import { openBoard } from "@stallion/client-sync";
import { useCallback, useEffect, useRef, useState } from "preact/hooks";
import { PinPrompt } from "./pin-prompt";
import { loadRecents, saveRecents, upsertRecent } from "./recents";
import { errorMessage, reportLink } from "./report";
import { boardLink, SharePanel } from "./share";
import { createSurface, type Surface, type SurfaceView, type Tool, type ToolMode } from "./surface";
import { type BoardSource, type Connection, openSource, syncUrlFor } from "./sync";
import { captureThumbnail } from "./thumbnail";
import { type HistoryState, Toolbar } from "./toolbar";

const EMPTY_HISTORY: HistoryState = { canUndo: false, canRedo: false };

const INITIAL_VIEW: SurfaceView = { level: 0, contentLevels: [] };

const THUMBNAIL_DELAY_MS = 2000;

const historyKey = (event: KeyboardEvent): "Undo" | "Redo" | undefined => {
  if (!(event.ctrlKey || event.metaKey) || event.altKey) return undefined;
  const key = event.key.toLowerCase();
  if (key === "z") return event.shiftKey ? "Redo" : "Undo";
  if (key === "y" && !event.shiftKey) return "Redo";
  return undefined;
};

const SURFACE_CLASS: Record<ToolMode, string> = {
  Pencil: "surface",
  Pan: "surface panning",
  Eraser: "surface erasing",
  Select: "surface selecting",
};

export function Board({ boardId }: { boardId: string }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [tool, setTool] = useState<Tool>({
    size: "Medium",
    primary: 0,
    secondary: 4,
    mode: "Pencil",
  });
  const [error, setError] = useState<string | undefined>(undefined);
  const [connection, setConnection] = useState<Connection>("LocalOnly");
  const [history, setHistory] = useState<HistoryState>(EMPTY_HISTORY);
  const [view, setView] = useState<SurfaceView>(INITIAL_VIEW);
  const [shareOpen, setShareOpen] = useState(false);
  const sourceRef = useRef<BoardSource | undefined>(undefined);
  const surfaceRef = useRef<Surface | undefined>(undefined);
  const toolRef = useRef(tool);
  toolRef.current = tool;
  const closeShare = useCallback(() => setShareOpen(false), []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    saveRecents(localStorage, upsertRecent(loadRecents(localStorage), { id: boardId }));
    const source = openSource({
      url: syncUrlFor(import.meta.env.VITE_SYNC_URL, window.location),
      boardId,
      openBoard,
      onConnection: setConnection,
      onError: setError,
    });
    sourceRef.current = source;
    const syncHistory = () =>
      setHistory({ canUndo: source.history.canUndo, canRedo: source.history.canRedo });
    const unobserve = source.history.observe(syncHistory);
    const onKey = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLInputElement) return;
      const action = historyKey(event);
      if (!action) return;
      event.preventDefault();
      if (action === "Undo") source.history.undo();
      else source.history.redo();
    };
    window.addEventListener("keydown", onKey);
    let thumbnailTimer: ReturnType<typeof setTimeout> | undefined;
    const scheduleThumbnail = () => {
      clearTimeout(thumbnailTimer);
      thumbnailTimer = setTimeout(() => {
        const thumbnail = captureThumbnail(canvas);
        if (!thumbnail) return;
        saveRecents(
          localStorage,
          upsertRecent(loadRecents(localStorage), { id: boardId, thumbnail }),
        );
      }, THUMBNAIL_DELAY_MS);
    };
    let surface: Surface | undefined;
    try {
      surface = createSurface(
        canvas,
        boardId,
        source,
        () => toolRef.current,
        setView,
        scheduleThumbnail,
      );
      surfaceRef.current = surface;
    } catch (failure) {
      setError(`Could not start the drawing surface: ${errorMessage(failure)}`);
    }
    return () => {
      clearTimeout(thumbnailTimer);
      window.removeEventListener("keydown", onKey);
      unobserve();
      sourceRef.current = undefined;
      setHistory(EMPTY_HISTORY);
      surfaceRef.current = undefined;
      surface?.dispose();
      source
        .close()
        .catch((failure: unknown) =>
          setError(`Could not close the board: ${errorMessage(failure)}`),
        );
    };
  }, [boardId]);

  return (
    <main class="board">
      <canvas
        ref={canvasRef}
        class={SURFACE_CLASS[tool.mode]}
        aria-label={`Drawing board ${boardId}`}
      />
      <Toolbar
        tool={tool}
        onChange={setTool}
        connection={connection}
        history={history}
        onUndo={() => sourceRef.current?.history.undo()}
        onRedo={() => sourceRef.current?.history.redo()}
        view={view}
        onLevel={(level) => surfaceRef.current?.zoomToLevel(level)}
        shareOpen={shareOpen}
        onShare={() => setShareOpen(!shareOpen)}
      />
      {shareOpen && (
        <SharePanel
          link={boardLink(window.location.origin, boardId)}
          source={sourceRef.current}
          onClose={closeShare}
        />
      )}
      {connection === "Locked" && (
        <PinPrompt
          lock={sourceRef.current?.lock}
          onJoin={(pin) =>
            sourceRef.current
              ? sourceRef.current.join(pin)
              : Promise.resolve({ ok: false, reason: "Closed", message: "the board is not open" })
          }
        />
      )}
      {error && (
        <div class="error" role="alert">
          <p>{error}. Strokes may not be saved; reload to try again.</p>
          <a href={reportLink(error)} target="_blank" rel="noreferrer">
            Report an issue
          </a>
        </div>
      )}
    </main>
  );
}
import type { StoredObject } from "@stallion/client-store";
import type {
  BoardLock,
  BoardOptions,
  BoardStatus,
  History,
  LiveObjects,
  PinResult,
  PinState,
  SetPinResult,
  StallionBoard,
} from "@stallion/client-sync";
import type { BBox } from "@stallion/geometry";
import { errorMessage } from "./report";

export type Connection = "Connected" | "Reconnecting" | "Offline" | "Locked" | "LocalOnly";

export const CONNECTION_LABEL: Record<Connection, string> = {
  Connected: "Connected",
  Reconnecting: "Reconnecting",
  Offline: "Offline",
  Locked: "Locked: enter the board PIN to join",
  LocalOnly: "Local only: strokes stay in this browser",
};

export const VIEW_DEBOUNCE_MS = 100;

export type Awareness = StallionBoard["awareness"];

export type DrawingSource = {
  view(viewport: BBox, zoom: number): void;
  commit(stored: StoredObject): void;
  erase(objectId: string): void;
  readonly objects: LiveObjects;
  readonly history: History;
  readonly awareness: Awareness | undefined;
  close(): Promise<void>;
};

export type BoardSource = DrawingSource & {
  readonly lock: BoardLock | undefined;
  join(pin: string): Promise<PinResult>;
  setPin(pin: string): Promise<SetPinResult>;
  pinState(): Promise<PinState>;
};

export type OpenBoard = (url: string, boardId: string, options?: BoardOptions) => StallionBoard;

export type SourceOptions = {
  url: string | undefined;
  boardId: string;
  openBoard: OpenBoard;
  onConnection: (connection: Connection) => void;
  onError: (message: string) => void;
};

export const connectionFor = (status: BoardStatus, online: boolean): Connection => {
  if (status === "Open") return "Connected";
  if (status === "NeedsPin") return "Locked";
  if (!online) return "Offline";
  return status === "Closed" ? "Offline" : "Reconnecting";
};

const debounced = (run: (viewport: BBox, zoom: number) => void) => {
  let timer: ReturnType<typeof setTimeout> | undefined;
  return {
    call(viewport: BBox, zoom: number): void {
      clearTimeout(timer);
      timer = setTimeout(() => run(viewport, zoom), VIEW_DEBOUNCE_MS);
    },
    cancel(): void {
      clearTimeout(timer);
    },
  };
};

export function openLocalSource(options: SourceOptions): BoardSource {
  const board = options.openBoard("", options.boardId, {
    localOnly: true,
    cache: { cap: Number.POSITIVE_INFINITY },
    onError: ({ reason }) => options.onError(reason),
  });
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    history: board.history,
    awareness: undefined,
    get lock() {
      return board.lock;
    },
    join: (pin) => board.join(pin),
    setPin: (pin) => board.setPin(pin),
    pinState: () => board.pinState(),
    close() {
      setView.cancel();
      return board.close();
    },
  };
}

export function openSyncSource(url: string, options: SourceOptions): BoardSource {
  const online = () => globalThis.navigator?.onLine !== false;
  const board = options.openBoard(url, options.boardId, {
    onStatus: (status) => options.onConnection(connectionFor(status, online())),
    onError: ({ tileKey, reason }) =>
      options.onError(`Sync failed${tileKey ? ` on tile ${tileKey}` : ""}: ${reason}`),
  });
  options.onConnection(connectionFor(board.status, online()));
  const setView = debounced((viewport, zoom) => board.setView(viewport, zoom));
  return {
    view: setView.call,
    commit: (stored) => board.put(stored),
    erase: (objectId) => board.remove(objectId),
    objects: board.objects,
    history: board.history,
    awareness: board.awareness,
    get lock() {
import { describe, expect, it } from "vitest";
import { lastOpenedLabel } from "./landing";

describe("lastOpenedLabel", () => {
  it("shows not opened yet for a board that was never opened", () => {
    expect(lastOpenedLabel(0, Date.now())).toBe("not opened yet");
  });

  it("shows a relative time for a board that was opened", () => {
    const now = Date.now();
    const oneHourAgo = now - 60 * 60 * 1000;
    expect(lastOpenedLabel(oneHourAgo, now)).toBe("1 hour ago");
  });
});
        BOARD_KEY,
        `the server refused the board connection ${target} ${failedHandshakes} times in a row; still retrying`,
