  [
    `      {recents.length > 0 && (`,
    `      <RemoteNotice remote={remote} />
      {recents.length > 0 && (`,
  ],
  ["                onBlur={commitNames}", "                onBlur={() => commitName(recent.id)}"],
  [
    `title="Remove from this device's recent boards"`,
    `title={api ? "Remove from your boards" : "Remove from this device's recent boards"}`,
  ],
]);
