:root {
  --paper: #fbfaf7;
  --panel: #ffffffee;
  --ink: #1f2328;
  --line: #d9d6cf;
  --accent: #0090ff;
  color-scheme: only light;
}

html,
body,
#app {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--paper);
